    "strat_reno": "Additive Increase / Multiplicative Decrease (AIMD)",
    "strat_cubic": "Fonction cubique — agressive sur les réseaux à haut BDP",
    "strat_bbr": "Basé sur un modèle — estime la bande passante et le RTT",
    "loss_resp_reno": "cwnd divisé par deux en cas de perte ; le timeout réinitialise à 1 MSS",
    "loss_resp_cubic": "cwnd *= 0,7 ; récupération concave-convexe via W(t) = C(t-K)^3 + Wmax",
    "loss_resp_bbr": "Ignore la perte ; continue au taux BDP estimé",
    "loss_impact_title": "Analyse de l'Impact de la Perte",
    "loss_impact_hint": "Au taux de perte configuré, chaque algorithme répond différemment. BBR est tolérant aux pertes par conception.",
    "recovery_reno": "AIMD : diviser cwnd par deux, recroissance linéaire",
    "recovery_cubic": "Récupération plus rapide via la fonction cubique",
    "recovery_bbr": "Aucune récupération nécessaire (tolérant aux pertes)",
    "notes_reno": "Conservateur ; le plus lent à récupérer sur les chemins à haut BDP",
    "notes_cubic": "Meilleur sur les LFN ; par défaut dans Linux depuis le noyau 2.6.19",
    "notes_bbr": "Meilleur débit sous perte ; peut causer des files d'attente s'il n'est pas ajusté",
    "phase_slow_start": "Slow Start",
    "phase_ca": "Congestion Avoidance",
    "phase_fast_recovery": "Fast Recovery",
    "sysctl_title": "Optimisation TCP Linux (sysctl)",
    "sysctl_subtitle": "Générez des commandes sysctl pour optimiser les tampons TCP Linux et le contrôle de congestion pour vos paramètres de chemin.",
    "sysctl_algo": "Algorithme de Contrôle de Congestion",
    "sysctl_apply_hint": "Appliquer avec : sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. Les valeurs sont calculées à partir de votre BDP.",
    "ref_title": "Référence d'Algorithme",
    "ref_reno_desc": "Algorithme AIMD classique. Le slow start double cwnd chaque RTT jusqu'à ssthresh. Le congestion avoidance ajoute ~1 segment par RTT. Sur 3 ACK dupliqués : ssthresh = cwnd/2, cwnd = ssthresh. Sur timeout : cwnd = 1 MSS. Équitable mais sous-utilise les chemins à haut BDP après perte.",
    "ref_cubic_desc": "Par défaut dans Linux. Utilise une fonction cubique W(t) = C(t-K)^3 + W_max (C=0,4, beta=0,7). Après perte, cwnd tombe à 70% de W_max, puis croît via la courbe concave-convexe. Plus agressif que Reno sur les long-fat networks. K = (W_max * 0,3 / C)^(1/3).",
    "ref_bbr_desc": "Algorithme basé sur un modèle de Google. Estime la bande passante du goulot d'étranglement et le RTT min au lieu d'utiliser la perte comme signal. Phases : Startup (gain 2,89x), Drain, ProbeBW (cycle de gain en 8 phases : 1,25/0,75/1...), ProbeRTT (4 segments environ toutes les 10s). Atteint un débit complet même avec perte.",
    "phase_startup": "Startup",
    "phase_drain": "Drain",
    "phase_probe_bw": "ProbeBW",
    "phase_probe_rtt": "ProbeRTT",
