    "plat_nxos_notes": "NX-OS utilise bootflash: par défaut. Vérifiez l'espace du système de fichiers avec \"dir bootflash:\". Le VRF doit joindre le serveur en IP ; vérifiez le routage par défaut ou le VRF de gestion.",
    "plat_junos_notes": "Les copies de fichiers sur Junos sont placées dans /var/tmp/ ou /var/db/config/. Utilisez \"show system storage\" pour vérifier l'espace disque. Les transferts TFTP peuvent nécessiter des configurations de protocole de routage Junos ou l'utilisation du mot-clé routing-instance.",
    "plat_eos_notes": "Les équipements Arista utilisent flash:. Vérifiez avec \"dir flash:\". Pour un haut débit, Arista prend en charge des copies HTTP/HTTPS natives hautement optimisées.",
    "plat_fortios_notes": "La restauration TFTP de FortiOS remplace l'image de démarrage et redémarre l'équipement automatiquement. À utiliser avec précaution. Sauvegardez toujours les fichiers de configuration au préalable.",
    "plat_panos_notes": "Palo Alto PAN-OS exige des autorisations d'administrateur CLI explicites pour exécuter les commandes d'importation de logiciels. Les logiciels peuvent également être téléchargés directement depuis les mises à jour officielles du support Palo Alto.",
    "plat_linux_notes": "Vérifiez les permissions de lecture/écriture du répertoire cible. Assurez-vous que le client (scp, curl) est installé. Les transferts HTTP/HTTPS via curl/wget sont hautement parallélisables.",
    "plat_f5_notes": "Vérifiez les processus bigstart et les permissions de route administrative de F5. Le dossier de destination /shared/images/ est l'emplacement par défaut des fichiers ISO F5.",
