    "double_nat_title": "Double NAT dans les déploiements CGNAT",
    "double_nat_body": "Dans un déploiement CGNAT typique, les abonnés effectuent également un NAT sur leur CPE — traduisant les adresses {rfc1918} vers leur adresse 100.64.0.0/10 assignée avant même que le trafic n'atteigne le NAT de l'opérateur. Ce double NAT casse l'UPnP et le mappage de ports automatique, complique la redirection de ports manuelle et constitue un point critique connu pour le jeu, la VoIP et toute application nécessitant des connexions entrantes.",
