    "desc_strategy_deterministic": "Le CGNAT alloue à l'avance un bloc fixe et réservé de ports sources à chaque abonné. Cela garantit la disponibilité des ports et réduit la surcharge syslog de 99 % (seule l'allocation de bloc est enregistrée, pas les sessions individuelles), mais limite le nombre total d'abonnés par IP publique.",
