    "scenario_overlap_desc": "Deux réseaux utilisent la même plage privée (ex: 192.168.1.0/24). Pour communiquer sans conflit IP, les deux côtés doivent effectuer un NAT. L'Hôte A traduit vers une IP de transit, et l'Hôte B traduit vers une IP de transit.",
