    "err_invalid_ip": "Format d'adresse IP invalide",
    "explanation_title": "Comprendre NAT vs PAT",
    "explanation_intro": "Le Network Address Translation (NAT) et le Port Address Translation (PAT) sont des techniques permettant de mapper un espace d'adressage IP vers un autre, principalement utilisées pour préserver les adresses IPv4 publiques limitées ou résoudre des conflits de sous-réseaux.",
    "nat_expl_title": "1. Qu'est-ce que le NAT ?",
    "nat_expl_desc": "Le NAT traduit les adresses IP sur une base 1-pour-1. Il peut être Statique (mappage permanent d'une IP privée vers une IP publique, idéal pour les serveurs accessibles publiquement) ou Dynamique (alloue une IP publique d'un pool à un hôte privé à la demande. Une fois toutes les IP publiques assignées, les hôtes suivants sont bloqués jusqu'à ce qu'une IP soit libérée). Les numéros de ports ne sont pas modifiés.",
    "pat_expl_title": "2. Qu'est-ce que le PAT (NAT Overload) ?",
    "pat_expl_desc": "Le PAT (ou Port Address Translation / NAT Overload) traduit à la fois l'adresse IP et le numéro de port source sur une base plusieurs-vers-un (N-pour-1). Plusieurs hôtes privés partagent une seule adresse IP publique en assignant des ports sources uniques (ex: 192.168.1.10:5000 et 192.168.1.11:5000 sont mappés vers 203.0.113.10:1024 et 203.0.113.10:1025). C'est la méthode standard pour les routeurs domestiques et l'accès Internet en entreprise.",
    "comparison_table_title": "Résumé Comparatif",
    "comp_header_feature": "Fonctionnalité",
    "comp_header_nat": "NAT (1-pour-1)",
    "comp_header_pat": "PAT (N-pour-1 / Overload)",
    "comp_row_ratio": "Ratio d'Adresses IP",
    "comp_row_ratio_nat": "1:1 (Une IP publique par hôte actif)",
