    "comp_row_port_nat": "Non (le port d'origine est préservé)",
    "comp_row_port_pat": "Oui (réécrit dynamiquement pour assurer l'unicité)",
    "comp_row_limit": "Limite de Capacité",
    "comp_row_limit_nat": "Égal au nombre d'IP dans le pool public",
