    "about_body": "iperf est un outil de mesure active de la bande passante maximale réalisable sur les réseaux IP. Un hôte fait office de serveur (écouteur) et un autre se connecte en tant que client pour envoyer (ou recevoir) du trafic via TCP, UDP ou SCTP, signalant le débit, la gigue et la perte de paquets. iperf3 (binaire iperf3) est une réécriture moderne avec sortie JSON et modes inverse/bidirectionnel ; iperf2 (binaire iperf) est multi-client et plus performant pour le Wi-Fi et le multicast. Les deux ne sont PAS compatibles — les deux extrémités doivent exécuter la même version.",
